# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM YÖNETİM ANLAYIŞINDA ADALET İLKESİ VE KURUMLARI</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Adalet İlkesinin Esasları</text>\n  <text x="40" y="95" font-size="12" fill="#1e3a8a">• Hak sahibine hakkını eksiksiz teslim etmek</text>\n  <text x="40" y="119" font-size="12" fill="#1e3a8a">• Kanun önünde yöneten ve yönetilen eşitliği</text>\n  <text x="40" y="143" font-size="12" fill="#1e3a8a">• Suçun şahsiliği ve masumiyet karinesi</text>\n  <text x="40" y="167" font-size="12" fill="#1e3a8a">• Yargı bağımsızlığı (Kadıların özerkliği)</text>\n  <rect x="40" y="182" width="280" height="44" rx="6" fill="#eff6ff" stroke="#60a5fa" stroke-width="1.5"/>\n  <text x="180" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">"Adalet mülkün (devletin ve düzenin) temelidir."</text>\n\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Tarihsel Adalet Uygulamaları</text>\n  <text x="375" y="95" font-size="12" fill="#78350f">• <tspan font-weight="bold">Medine Vesikası:</tspan> Çok kültürlü hukuki güvence</text>\n  <text x="375" y="119" font-size="12" fill="#78350f">• <tspan font-weight="bold">Hz. Ömer\'in Adaletnamesi:</tspan> Yargı usulü ilkeleri</text>\n  <text x="375" y="143" font-size="12" fill="#78350f">• <tspan font-weight="bold">Dîvân-ı Mezâlim:</tspan> Yöneticilerin denetlendiği</text>\n  <text x="385" y="160" font-size="11" fill="#78350f">yüksek idari yargı ve şikâyet mahkemesi</text>\n  <text x="375" y="184" font-size="12" fill="#78350f">• <tspan font-weight="bold">Osmanlı Adaletnameleri:</tspan> Halkı memur ve</text>\n  <text x="385" y="201" font-size="11" fill="#78350f">yönetici suiistimallerine karşı koruyan fermanlar</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">LİYAKAT (EHLİYET) VE İSTİŞARE (ŞÛRA) İLKELERİ</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Liyakat (İşi Ehline Verme)</text>\n  <text x="40" y="95" font-size="12" fill="#14532d">• Ölçüt: Bilgi, uzmanlık, tecrübe ve güvenilirlik</text>\n  <text x="40" y="119" font-size="12" fill="#14532d">• Yasaklanan: İltimas (torpil / kayırmacılık)</text>\n  <text x="40" y="143" font-size="12" fill="#14532d">• <tspan font-weight="bold">Yusuf Suresi 55:</tspan> "Beni ülke hazinelerine</text>\n  <text x="50" y="160" font-size="11" fill="#14532d">tayin et; çünkü ben koruyucuyum ve bilgiliyim."</text>\n  <rect x="40" y="176" width="280" height="48" rx="6" fill="#f0fdf4" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="180" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Nebevi Örnek: Ebû Zer el-Gıfârî ve Üsâme b. Zeyd</text>\n  <text x="180" y="213" text-anchor="middle" font-size="10" fill="#14532d">Sevgi değil, görevin gerektirdiği ehliyet esas alınmıştır.</text>\n\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">İstişare / Şûra (Ortak Akıl)</text>\n  <text x="375" y="95" font-size="12" fill="#581c87">• <tspan font-weight="bold">Âl-i İmrân 159:</tspan> "İş konusunda onlarla</text>\n  <text x="385" y="112" font-size="11" fill="#581c87">istişare et (danış)."</text>\n  <text x="375" y="136" font-size="12" fill="#581c87">• <tspan font-weight="bold">Şûra 38:</tspan> "Onların işleri aralarında danışma iledir."</text>\n  <text x="375" y="160" font-size="12" fill="#581c87">• Hendek Savaşı\'nda Selmân-ı Fârisî\'nin görüşü</text>\n  <rect x="375" y="176" width="285" height="48" rx="6" fill="#faf5ff" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="517" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Kurumsal Şûra Meclisleri</text>\n  <text x="517" y="213" text-anchor="middle" font-size="10" fill="#581c87">Dört Halife Şûrası • Dîvân-ı Saltanat • Dîvân-ı Hümâyun</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MEŞRUİYET İLKESİ (HUKUKUN ÜSTÜNLÜĞÜ VE SINIRLI YETKİ)</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">1. Yönetime Gelişte Meşruiyet</text>\n  <text x="38" y="98" font-size="11" fill="#0c4a6e">• Halkın ve şûra ehlinin</text>\n  <text x="46" y="114" font-size="11" font-weight="bold" fill="#0369a1">rızası ve biatı</text>\n  <text x="38" y="138" font-size="11" fill="#0c4a6e">• Yönetici ile toplum</text>\n  <text x="46" y="154" font-size="11" fill="#0c4a6e">arasında karşılıklı</text>\n  <text x="46" y="170" font-size="11" fill="#0c4a6e">hukuki sözleşme (akit)</text>\n  <text x="38" y="198" font-size="11" font-weight="bold" fill="#0284c7">Zorbalık değil, toplumsal onay</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Uygulamada Meşruiyet</text>\n  <text x="260" y="98" font-size="11" fill="#78350f">• Kararların Kur\'an, Sünnet</text>\n  <text x="268" y="114" font-size="11" fill="#78350f">ve hukuk ilkelerine uyumu</text>\n  <text x="260" y="138" font-size="11" fill="#78350f">• Temel hakların (can, mal,</text>\n  <text x="268" y="154" font-size="11" fill="#78350f">akıl, din, nesil) korunması</text>\n  <text x="260" y="178" font-size="11" fill="#78350f">• Osmanlı\'da kanunnamelerin</text>\n  <text x="268" y="198" font-size="11" font-weight="bold" fill="#b45309">hukuka uygunluk denetimi</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">3. İtaatin Meşru Sınırı</text>\n  <text x="483" y="98" font-size="11" fill="#14532d">• Ulü\'l-emre (yöneticilere)</text>\n  <text x="491" y="114" font-size="11" fill="#14532d">itaat kamu düzeni içindir.</text>\n  <text x="483" y="138" font-size="11" font-weight="bold" fill="#15803d">• "İtaat ancak maruftadır</text>\n  <text x="491" y="154" font-size="11" font-weight="bold" fill="#15803d">(iyi ve meşru olandadır)."</text>\n  <text x="483" y="178" font-size="11" fill="#14532d">• Zulüm ve haram emrine</text>\n  <text x="491" y="198" font-size="11" fill="#14532d">itaat edilmez.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
